import{_ as l,o as i,c as t,aA as e}from"./chunks/framework.BMzE2Z9R.js";const d=JSON.parse('{"title":"NARS各版实现 索引","description":"","frontmatter":{"comments":true},"headers":[],"relativePath":"nars/impl/index.md","filePath":"nars/impl/index.md","lastUpdated":1778399398000}'),r={name:"nars/impl/index.md"};function s(o,a,n,h,c,u){return i(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="nars各版实现-索引" tabindex="-1">NARS各版实现 索引 <a class="header-anchor" href="#nars各版实现-索引" aria-label="Permalink to &quot;NARS各版实现 索引&quot;">​</a></h1><p>综合NARS在各处的实现情况，本文添加了NARS各版实现索引。</p><p>该索引将专注于NARS各版实现的分类存档。索引将以<strong>编程语言</strong>为主要分类依据，内部排序大部分将按<strong>实现时间/发布时间</strong>组织。编程语言的排序不分先后。</p><p>（TODO: 具体介绍前言仍可扩充与润色。）</p><div class="callout" data-callout="warning"><div class="callout-title"><div class="callout-title-icon"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-alert-triangle"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"></path><path d="M12 9v4"></path><path d="M12 17h.01"></path></svg></div><div class="callout-title-inner">注意</div></div><div class="callout-content"><p></p><p>本板块不讨论编程语言。</p><p>若想讨论与编程语言自身相关的话题，可移步至其它技术论坛网站。</p></div></div><h2 id="索引" tabindex="-1">索引 <a class="header-anchor" href="#索引" aria-label="Permalink to &quot;索引&quot;">​</a></h2><h3 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C&quot;">​</a></h3><ul><li><a href="./impls/ona" title="OpenNARS for Applications">ONA</a> (OpenNARS for Applications)</li></ul><h3 id="clojure" tabindex="-1">Clojure <a class="header-anchor" href="#clojure" aria-label="Permalink to &quot;Clojure&quot;">​</a></h3><ul><li><a href="./impls/narjure" title="OpenNARS 2.x">Narjure</a> (OpenNARS 2.x)</li></ul><h3 id="java" tabindex="-1">Java <a class="header-anchor" href="#java" aria-label="Permalink to &quot;Java&quot;">​</a></h3><ul><li><a href="./impls/opennars" title="OpenNARS 1.x / 3.x">OpenNARS</a> (OpenNARS 1.x / 3.x)</li></ul><h3 id="javascript-typescript" tabindex="-1">JavaScript/TypeScript <a class="header-anchor" href="#javascript-typescript" aria-label="Permalink to &quot;JavaScript/TypeScript&quot;">​</a></h3><ul><li><a href="./impls/nars_cxin_py_to_ts">NARS CXin Py to TS</a></li></ul><h3 id="julia" tabindex="-1">Julia <a class="header-anchor" href="#julia" aria-label="Permalink to &quot;Julia&quot;">​</a></h3><ul><li><a href="./impls/openjunars">OpenJunars</a></li></ul><h3 id="python" tabindex="-1">Python <a class="header-anchor" href="#python" aria-label="Permalink to &quot;Python&quot;">​</a></h3><ul><li><a href="./impls/nars_python">NARS-Python</a></li><li><a href="./impls/pynars">PyNARS</a></li></ul><h3 id="rust" tabindex="-1">Rust <a class="header-anchor" href="#rust" aria-label="Permalink to &quot;Rust&quot;">​</a></h3><ul><li><a href="./impls/20nar1">20NAR1</a></li><li><a href="./impls/narst">Narst</a>（截止至2024-07-26，尚不完整）</li><li><a href="./impls/narust">NARust</a></li></ul><h3 id="swift" tabindex="-1">Swift <a class="header-anchor" href="#swift" aria-label="Permalink to &quot;Swift&quot;">​</a></h3><ul><li><a href="./impls/nars_swift">NARS-Swift</a></li></ul><h2 id="版本收录-投稿" tabindex="-1">版本收录&amp;投稿 <a class="header-anchor" href="#版本收录-投稿" aria-label="Permalink to &quot;版本收录&amp;投稿&quot;">​</a></h2><div class="callout" data-callout="question"><div class="callout-title"><div class="callout-title-icon"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-help-circle"><circle cx="12" cy="12" r="10"></circle><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3"></path><path d="M12 17h.01"></path></svg></div><div class="callout-title-inner">需要添加自己的版本？</div></div><div class="callout-content"><p></p><p>若实现者有自己的一版NARS实现，可<a href="https://github.com/Hailaylin/agi-society-cn/issues/new" target="_blank" rel="noreferrer">在GitHub提issue</a>，或在文末评论区发言。</p><p>同样也欢迎贡献者对遗漏的版本投稿！</p><p>投稿NARS实现前，可检查以下几点：</p><ol><li>有GitHub/Gitee代码仓库 <ul><li>推荐开源</li></ul></li><li>有Narsese语言实现 <ul><li>不论是内建数据结构，还是借助外部语法解析库</li></ul></li><li>有NAL实现 <ul><li>不限层级，不限算法</li></ul></li><li>有Demo演示 <ul><li>可为视频，也可为在线交互页面</li></ul></li></ol></div></div>',24)])])}const m=l(r,[["render",s]]);export{d as __pageData,m as default};
